// Settings → GitHub section, AS GRAPH SOURCE (#3658, epic #3604). Transcribed from the live feature file: the runtime
// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui
// design system + the store via appModules, the setting cards + page helpers via the settings graph-
// platform, and the sibling section pages as @/components/* graph records). Behaviour runs here.
import { ConnectGithubCard } from "@/features/settings/cards/ConnectGithubCard";
import { RepoCredentialsCard } from "@/features/settings/cards/RepoCredentialsCard";
import { useAppStore } from "@/store";
import { Stack } from "@/shared/ui/layout/Stack";
import { SettingsPageHeader } from "@/features/settings/pages/SettingsPageHeader";

export function GithubPage() {
  const { githubConnected, githubUser } = useAppStore();

  return (
    <Stack gap={18} style={{ maxWidth: 820 }}>
      <SettingsPageHeader
        title="GitHub"
        description="Manage GitHub device authentication, OAuth profiles, and scoped repository credentials."
      />

      {/* GitHub Cards */}
      <ConnectGithubCard />
      {githubConnected && githubUser && (
        <RepoCredentialsCard />
      )}
    </Stack>
  );
}
